describe('PDF Inline Viewer Upload', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('[data-testid="file-input"]').should('be.visible');
  });

  it('should display uploaded PDF in inline viewer', () => {
    const fileName = 'sample.pdf';

    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="pdf-viewer"]', { timeout: 10000 }).should('be.visible');

    cy.get('[data-testid="pdf-viewer"] iframe').should('exist');

    cy.get('[data-testid="pdf-filename"]').should('contain', fileName);

    cy.get('[data-testid="pdf-viewer"]').should('have.class', 'active');
  });

  it('should handle large PDF files without errors', () => {
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/large-document.pdf', { force: true });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="loading-spinner"]', { timeout: 15000 }).should('not.exist');

    cy.get('[data-testid="pdf-viewer"]').should('be.visible');

    cy.get('[data-testid="error-message"]').should('not.exist');

    cy.get('[data-testid="pdf-page-count"]').should('contain', /\d+/);
  });

  it('should reject non-PDF file uploads', () => {
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/document.txt', { force: true });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');

    cy.get('[data-testid="error-message"]').should('contain', 'PDF');

    cy.get('[data-testid="pdf-viewer"]').should('not.exist');
  });

  it('should allow downloading the displayed PDF', () => {
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="pdf-viewer"]', { timeout: 10000 }).should('be.visible');

    cy.get('[data-testid="download-button"]').should('be.visible');

    cy.get('[data-testid="download-button"]').click();

    cy.readFile('cypress/downloads/sample.pdf').should('exist');
  });

  it('should navigate between PDF pages', () => {
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/multi-page.pdf', { force: true });

    cy.get('[data-testid="upload-button"]').click();

    cy.get('[data-testid="pdf-viewer"]', { timeout: 10000 }).should('be.visible');

    cy.get('[data-testid="current-page"]').should('contain', '1');

    cy.get('[data-testid="next-page-button"]').click();

    cy.get('[data-testid="current-page"]').should('contain', '2');

    cy.get('[data-testid="previous-page-button"]').click();

    cy.get('[data-testid="current-page"]').should('contain', '1');
  });
});
